"""
bc.py -- behaviour cloning of the planner into a k-masked set-actor.

Fixes F3/F5/F6:
  * the regression target is the expert's DISPLACEMENT command (unit-ball units) and its channel; neither is
    an input feature (own position enters only as pos/W, the target is a movement) -- test_gates G0b checks it;
  * observations are the env's OWN observations, regenerated by replaying the stored expert actions through
    CommEnv (so train and deploy observation distributions are the same object);
  * the dataset stores seeds + actions only, so one file serves every k.
"""
from __future__ import annotations
import time
import numpy as np
import torch
import torch.nn.functional as F

from commenv import CommEnv, EnvConfig, Obs
from models import Actor


def replay_observations(seeds, cfg: EnvConfig, actions, channels):
    """Roll the expert through the env; return actor observations (flattened rows) + targets."""
    env = CommEnv(cfg, seeds)
    obs = env.reset()
    rows, A, Cc = [], [], []
    for t in range(cfg.T):
        rows.append(obs.flat())
        a = torch.tensor(actions[:, t]); c = torch.tensor(channels[:, t]).long()
        A.append(a.reshape(-1, 2)); Cc.append(c.reshape(-1))
        obs, _, _, _ = env.step(a, c)
    cat = lambda xs: torch.cat(xs, 0)
    o = Obs(*[cat([getattr(r, f) for r in rows]) for f in Obs._fields])
    return o, cat(A), cat(Cc)


def load_dataset(path, cfg: EnvConfig):
    d = torch.load(path, weights_only=False)
    return d["seeds"], d["actions"], d["channels"], d["expert_return"]


def _dihedral_mats():
    out = []
    for sw in (0, 1):
        for fx in (1.0, -1.0):
            for fy in (1.0, -1.0):
                P = torch.tensor([[0., 1.], [1., 0.]]) if sw else torch.eye(2)
                out.append(torch.diag(torch.tensor([fx, fy])) @ P)
    return torch.stack(out)                                   # [8,2,2]
_D8 = _dihedral_mats()


def augment(o: Obs, a, g: torch.Generator):
    """
    Random element of the square's symmetry group (4 rotations x reflection) applied to a batch.
    The physics (square world, isotropic path loss, reflecting boundaries, distance masks) is invariant,
    so (obs, action) -> (g.obs, g.action) is another valid expert sample: an exact 8x data multiplier.
    """
    n = a.shape[0]
    M = _D8[torch.randint(0, 8, (n,), generator=g)]                         # [n,2,2]
    mv = lambda x: torch.einsum("nij,n...j->n...i", M, x)
    sf = o.sf.clone(); sf[:, :2] = mv(sf[:, :2] - 0.5) + 0.5
    uf = torch.cat([mv(o.uf[..., 0:2]), mv(o.uf[..., 2:4])], -1)
    af = torch.cat([mv(o.af[..., 0:2]), o.af[..., 2:]], -1)
    return Obs(sf, uf, o.um, af, o.am), mv(a)


def bc_loss(actor, o, a, c, w_ch=1.0):
    mu, logits = actor(o)
    return F.mse_loss(mu, a) + w_ch * F.cross_entropy(logits, c), F.mse_loss(mu, a).item(), \
           (logits.argmax(-1) == c).float().mean().item()


def train_bc(cfg: EnvConfig, train_path, val_path, seed=0, epochs=30, bs=1024, lr=1e-3, verbose=True,
             aug=True, d=64):
    torch.manual_seed(seed)
    tr_seeds, tr_a, tr_c, _ = load_dataset(train_path, cfg)
    va_seeds, va_a, va_c, _ = load_dataset(val_path, cfg)
    o_tr, a_tr, c_tr = replay_observations(tr_seeds, cfg, tr_a, tr_c)
    o_va, a_va, c_va = replay_observations(va_seeds, cfg, va_a, va_c)
    actor = Actor(cfg, d=d)
    opt = torch.optim.Adam(actor.parameters(), lr=lr)
    n = a_tr.shape[0]
    steps = epochs * ((n + bs - 1) // bs)
    sched = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=lr, total_steps=steps)
    g = torch.Generator().manual_seed(seed)
    t0 = time.time()
    hist = []
    for ep in range(epochs):
        perm = torch.randperm(n, generator=g)
        for i in range(0, n, bs):
            idx = perm[i:i + bs]
            ob, ab = o_tr.index(idx), a_tr[idx]
            if aug:
                ob, ab = augment(ob, ab, g)
            loss, _, _ = bc_loss(actor, ob, ab, c_tr[idx])
            opt.zero_grad(); loss.backward(); opt.step(); sched.step()
        if (ep + 1) % 5 == 0 or ep == 0:
            with torch.no_grad():
                _, mse, acc = bc_loss(actor, o_va, a_va, c_va)
            hist.append((ep + 1, mse, acc))
            if verbose:
                print(f"  BC seed {seed} ep {ep+1:3d}  val pos-MSE {mse:.4f}  val channel-acc {acc:.3f}  ({time.time()-t0:.0f}s)", flush=True)
    return actor, hist
